[{"i":0,"name":"未标定区域","salesTax":0,"pollTax":0,"treasury":0,"neighbors":[2,17,18,15,4],"diplomacy":[["Dhodh-Dirdrian War","Dhodh declared a war on its rival Dirdra","Dirdra's ally Kaynakyurt joined the war on defenders side","Dirdra's ally Nunarg joined the war on defenders side","Frightened by Dhodh, Binayan severed the defense pact with Dirdra","Dirdra's ally Melathpalar joined the war on defenders side"],["Laug-Pretatryxian War","Laug declared a war on its rival Pretatryx","Laug's vassal Lurtha joined the war on attackers side","Laug's vassal Lyanololo joined the war on attackers side","Frightened by Laug, Dhodh severed the defense pact with Pretatryx","Pretatryx's ally Grasia joined the war on defenders side","Laug's ally Al-Nindyl avoided entering the war","Laug's ally Melathpalar avoided entering the war","Laug's ally Eanoth joined the war on attackers side"],["Yeseneli-Arelian War","Yeseneli declared a war on its rival Areli","Frightened by Yeseneli, Algyurt severed the defense pact with Areli","Yeseneli's ally Fayhostia joined the war on attackers side"],["Algyurt-Edikyurtian War","Algyurt declared a war on its rival Edikyurt"]],"urban":0,"rural":31.74729347229004,"burgs":0,"area":3791,"cells":27,"provinces":[],"note":""}]
[{"i":0,"cell":0,"x":0,"y":0,"removed":true},{"i":1,"name":"乾京","cell":3039,"x":1015,"y":400,"state":0,"culture":0,"feature":1,"capital":0,"port":0,"group":"capital","lock":true,"note":"大乾帝都；宫城在泊台广场东面，但此总图不指定宫城局部坐标。乾京与南邵间总路程三千七百里。","label":{"dx":0,"dy":-104,"pathPoints":[]}},{"i":2,"name":"南邵城","cell":7067,"x":1010,"y":945,"state":0,"culture":0,"feature":1,"capital":0,"port":0,"group":"city","lock":true,"note":"北靠群山，东、西、南近郊为肥沃平原。四方城郭、西门入城；清河绕城。","label":{"dx":0,"dy":-93,"pathPoints":[]}},{"i":3,"name":"荒村 · 皇天庙＊","cell":5573,"x":875,"y":750,"state":0,"culture":0,"feature":1,"capital":0,"port":0,"group":"monastery","lock":true,"note":"广安—南邵郡界附近的无名荒村，小庙在村东南角。这里只标大致区域；准确距离、郡界位置及所属郡未知。","label":{"dx":-150,"dy":8,"pathPoints":[]}},{"i":4,"name":"大桐县城＊","cell":8556,"x":1075,"y":1145,"state":0,"culture":0,"feature":1,"capital":0,"port":0,"group":"city","lock":true,"note":"离开大桐返回南邵的官道初段向北，当日到南邵。故放在南向道路区域作约位，具体偏角与距离未知。","label":{"dx":155,"dy":3,"pathPoints":[]}}]
